  const renderAnim = async (o) => { setDlg(null); if (!scene.activeCam) return toast('Add a camera to render'); const mimes = ['video/webm;codecs=vp9', 'video/webm;codecs=vp8', 'video/webm'].filter((m) => MediaRecorder.isTypeSupported(m)); if (!mimes.length) return toast('This browser cannot record video'); const { resX, resY } = scene.world; const a = h.ref.current.anim; const total = a.end - a.start + 1; setBusy({ pct: 0, label: 'Rendering animation…' }); E.current.cancel = false;
    await withRender(Math.round(resX * o.scale / 2) * 2, Math.round(resY * o.scale / 2) * 2, async (c) => { const stream = c.captureStream(a.fps); const mr = new MediaRecorder(stream, { mimeType: mimes[0], videoBitsPerSecond: 8e6 }); const chunks = []; mr.ondataavailable = (ev) => ev.data.size && chunks.push(ev.data); const done = new Promise((r) => { mr.onstop = r; }); mr.start(200); for (let i = 0; i < total; i++) { if (E.current.cancel) break; drawFinal(a.start + i); setBusy({ pct: i / total, label: `Frame ${i + 1} of ${total}` }); await new Promise((r) => setTimeout(r, 1000 / a.fps)); } mr.stop(); await done; if (!E.current.cancel) { download(new Blob(chunks, { type: 'video/webm' }), 'animation.webm'); toast('Animation exported'); } }); setBusy(null); };
