  const importMesh = async () => { const f = await pickFile('.obj,.stl'); if (!f) return; try { let added = []; if (/\.obj$/i.test(f.name)) added = MS.parseOBJ(await readAsText(f)).map((x) => ({ name: x.name, mesh: x.mesh })); else added = [{ name: f.name.replace(/\.[^.]+$/, ''), mesh: MS.parseSTL(await f.arrayBuffer()) }]; if (!added.length) throw new Error('No geometry found'); const objs = added.map((x) => { const r = MS.recenter(x.mesh); const b = MS.bounds(r.mesh); const size = Math.max(b.hi[0] - b.lo[0], b.hi[1] - b.lo[1], b.hi[2] - b.lo[2]) || 1; const k = size > 20 ? 4 / size : 1; return mkObject('mesh', { name: names(x.name), mesh: k !== 1 ? MS.scaleMesh(r.mesh, k) : r.mesh, pos: r.offset.map((c) => c * k), smooth: false, mat: mkMat() }); }); upd((s) => ({ ...s, objs: [...s.objs, ...objs] })); setSel(new Set(objs.map((o) => o.id))); setActive(objs[objs.length - 1].id); frame(false); toast(`Imported ${objs.length} object${objs.length > 1 ? 's' : ''} (${objs.reduce((a, o) => a + o.mesh.f.length, 0)} faces)`); } catch (e) { toast('Import failed: ' + e.message); } };
  const saveProject = () => { download(new Blob([JSON.stringify({ kind: 'techomato-3d', scene })], { type: 'application/json' }), `${safeName('scene')}.t3d.json`); };
  const openProject = async () => { const f = await pickFile('.json'); if (!f) return; try { const d = JSON.parse(await readAsText(f)); if (d.kind !== 'techomato-3d') throw new Error('not a 3D Studio file'); h.reset(d.scene); selectOnly(null); leaveEdit(); toast('Scene opened'); } catch (e) { toast('Could not open: ' + e.message); } };
  const newProject = async () => { if (!(await ask({ title: 'New scene', message: 'Discard the current scene and start a new one?', okText: 'New scene' }))) return; h.reset(newScene()); selectOnly(null); leaveEdit(); viewR.current = defaultView(); bump(); };
  const restored = useRef(false); const saveT = useRef(0);
