  useEffect(() => { if (!restored.current) return undefined; clearTimeout(saveT.current); setSave('Unsaved changes'); saveT.current = setTimeout(async () => { const ok = await idbSet('threed-project', { scene }); setSave(ok ? 'Autosaved' : 'Autosave unavailable'); }, 2500); return () => clearTimeout(saveT.current); }, [scene]);

