  const vec3 = (label, key, chan, o) => <PanelBox title={label} actions={<button type="button" className="stu-ib sm" aria-label={`Keyframe ${label}`} title="Insert keyframe for this channel" onClick={() => upd((s) => insertKey(s, [o.id], s.frame, [chan]))}><Icon name={scene.anim.keys[o.id] && scene.anim.keys[o.id][chan] ? 'keyframe' : 'keyframeO'} size={12} /></button>}>{[0, 1, 2].map((i) => <Num key={i} label={AXN[i]} value={+o[key][i].toFixed(3)} min={-10000} max={10000} step={key === 'rot' ? 1 : 0.1} slider={false} unit={key === 'rot' ? '°' : key === 'scl' ? '' : 'm'} digits={key === 'rot' ? 1 : 3} onChange={(v) => setObj(o.id, (x) => ({ ...x, [key]: x[key].map((c, k) => (k === i ? v : c)) }), true)} onCommit={() => { liveEnd(); afterXform([o.id]); }} />)}</PanelBox>;
