              {(() => { const n = scene.anim.end - scene.anim.start; const step = n > 400 ? 50 : n > 150 ? 20 : n > 60 ? 10 : 5; const out = []; for (let f = Math.ceil(scene.anim.start / step) * step; f <= scene.anim.end; f += step) out.push(<i key={f} style={{ left: `${((f - scene.anim.start) / n) * 100}%` }}><span>{f}</span></i>); return out; })()}
